const items = $input.all();
const data = items[0].json;
const works = (data.message && data.message.items) || [];
const requestedFormat = $('Webhook').item.json.body.format || 'all';

const citations = works.map(work => {
  const authors = (work.author || []).map(a => ({
    last: a.family || '',
    first: a.given || '',
    full: `${a.family || ''}, ${a.given || ''}`
  }));
  const year = work.issued && work.issued['date-parts'] && work.issued['date-parts'][0] ? work.issued['date-parts'][0][0] : 'n.d.';
  const title = (work.title && work.title[0]) || 'Untitled';
  const journal = (work['container-title'] && work['container-title'][0]) || '';
  const volume = work.volume || '';
  const issue = work.issue || '';
  const pages = work.page || '';
  const doi = work.DOI || '';

  // APA 7th
  const authorApa = authors.length > 0 ? authors.map(a => `${a.last}, ${a.first.charAt(0)}.`).join(', ') : 'Unknown';
  const apa = `${authorApa} (${year}). ${title}. *${journal}*${volume ? `, *${volume}*` : ''}${issue ? `(${issue})` : ''}${pages ? `, ${pages}` : ''}.${doi ? ` https://doi.org/${doi}` : ''}`;

  // MLA 9th
  const authorMla = authors.length > 0 ? `${authors[0].last}, ${authors[0].first}` + (authors.length > 1 ? ', et al.' : '') : 'Unknown';
  const mla = `${authorMla}. "${title}." *${journal}*${volume ? `, vol. ${volume}` : ''}${issue ? `, no. ${issue}` : ''}, ${year}${pages ? `, pp. ${pages}` : ''}.${doi ? ` https://doi.org/${doi}` : ''}`;

  // Chicago
  const authorChicago = authors.length > 0 ? authors.map(a => `${a.last}, ${a.first}`).join(', ') : 'Unknown';
  const chicago = `${authorChicago}. "${title}." *${journal}* ${volume}${issue ? `, no. ${issue}` : ''} (${year})${pages ? `: ${pages}` : ''}.${doi ? ` https://doi.org/${doi}` : ''}`;

  return { title, authors: authors.map(a => a.full), year, doi, apa, mla, chicago, score: work.score || 0 };
});

return [{
  json: {
    query: $('Webhook').item.json.body.title || $('Webhook').item.json.body.doi || '',
    resultCount: citations.length,
    format: requestedFormat,
    citations
  }
}];
